            {"question":"Financial policies are concerned with hospital personnel employment and retirement.","options":["True","False"],"answer":"False"},
            {"question":"Personnel policies may address hiring, promotion, termination, and retirement.","options":["True","False"],"answer":"True"},
            {"question":"Departmental policies apply only to a specific department or individual positions.","options":["True","False"],"answer":"True"},
            {"question":"Policies should be fair and unbiased.","options":["True","False"],"answer":"True"},
            {"question":"Policies should never be revised once established.","options":["True","False"],"answer":"False"},
            {"question":"Policies should be communicated to those affected by them.","options":["True","False"],"answer":"True"},
            {"question":"A procedure consists of steps arranged in chronological sequence.","options":["True","False"],"answer":"True"},
            {"question":"Procedures describe the exact manner in which certain activities should be accomplished.","options":["True","False"],"answer":"True"},
            {"question":"Written procedures promote efficiency, safety, and consistency.","options":["True","False"],"answer":"True"},
