            {"question":"Who from the following is the first line of management?","options":["Manager","Administrator","Supervisor","Head nurse"],"answer":"Head nurse"},
            {"question":"Who from the following is directing an agency to achieve objectives?","options":["Manager","Administrator","Supervisor","Head nurse"],"answer":"Manager"},
            {"question":"Which level is responsible for first line managers?","options":["Top management level","Middle management level","Low management level","Top administration level"],"answer":"Middle management level"},
            {"question":"The ability to communicate and motivate employee is:","options":["Conceptual skills","Technical skills","Human skills","Practical skills"],"answer":"Human skills"},
            {"question":"A statement of beliefs and values that direct practice is:","options":["Mission","Vision","Philosophy","Goal"],"answer":"Philosophy"},
            {"question":"A series of steps in a chronological sequence is:","options":["Vision","Philosophy","Policies","Procedure"],"answer":"Procedure"},
            {"question":"The minimum educational qualification of a head nurse is:","options":["Secondary school of nursing (3 years)","Secondary school of nursing (5 years)","Technical institute of nursing","A bachelor degree in nursing"],"answer":"A bachelor degree in nursing"},
