            {"question":"What is the type of spread of COVID-19 in 2019 health sector problem type?","options":["Structured problems","Routine problem","Unstructured problems","Long term problem"],"answer":"Unstructured problems"},
            {"question":"Which style is used for solving climate change health effects after next 5 years?","options":["Behavioral style","Directive style","Conceptual style","Analytical style"],"answer":"Conceptual style"},
            {"question":"Managing time effectively so that the right time is allocated to the right activity refers to:","options":["Time waster","Time management","Planning","Organizing"],"answer":"Time management"},
            {"question":"To use your time effectively, you must determine what you want to use it for. This principle is called:","options":["One thing at a time","Delegation","Clarity of purpose","Evaluation"],"answer":"Clarity of purpose"},
            {"question":"Something that prevents a person from accomplishing a job or achieving a goal is defined as:","options":["Procrastination","Time waster","Internal factor","Disorganization"],"answer":"Time waster"},
            {"question":"The principle of One person / one boss where each person has one manager is known as:","options":["Chain of command","Unity of command","Span of control","Delegation"],"answer":"Unity of command"},
            {"question":"The number of subordinates that can be adequately supervised by one supervisor is defined as:","options":["Span of control","Unity of command","Departmentation","Specialization"],"answer":"Span of control"},
            {"question":"What is the first step in delegation process?","options":["The delegation of authority","Creation of accountability","The allocation of duties","The assignment of responsibility"],"answer":"The allocation of duties"},
            {"question":"Power derived from the position held in the organization is:","options":["Technical authority","Legal authority","Authority","Operational authority"],"answer":"Authority"},
            {"question":"The Ministry of Health holds which type of authority?","options":["Operational authority","Technical authority","Legal authority","Ultimate authority"],"answer":"Legal authority"},
            {"question":"The process of grouping activities into administrative units is called:","options":["Specialization","Departmentation","Organizing","Staffing"],"answer":"Departmentation"},
            {"question":"A principle stating that a person should perform a single leading function is:","options":["Specialization","Departmentation","Unity of command","Chain of command"],"answer":"Specialization"},
            {"question":"A numerical description of expected income and expenditures for a specified period is a:","options":["Financial report","Budget","Balance sheet","Operating plan"],"answer":"Budget"},
            {"question":"What is the largest budget in healthcare?","options":["Operating budget","Capital budget","Personnel budget","Cash budget"],"answer":"Personnel budget"},
            {"question":"The budget that reflects expenses change in response to volume of service (such as electricity, repairs, and supplies) is:","options":["Operating budget","Capital budget","Cash budget","Personnel budget"],"answer":"Operating budget"},
            {"question":"Capital budgets are used to plan for the purchase of:","options":["Daily supplies","Buildings or major equipment","Staff salaries","Utility bills"],"answer":"Buildings or major equipment"},
            {"question":"The personal force that energizes, directs, sustains behavior toward a goal is:","options":["Directing","Leadership","Motivation","Supervision"],"answer":"Motivation"},
            {"question":"The process of determining and assigning the right personnel with right qualifications to the job at the right time is:","options":["Directing","Organizing","Staffing","Controlling"],"answer":"Staffing"},
            {"question":"Which control type focuses on preventing problems before they occur by setting pre-conditions?","options":["Feedback control","Concurrent control","Feedforward / Predictive control","Operational control"],"answer":"Feedforward / Predictive control"},
            {"question":"Real-time control that corrects problems as they happen during performance is known as:","options":["Feedback control","Concurrent control","Feedforward control","Financial control"],"answer":"Concurrent control"},
            {"question":"In the controlling process, SMART / M stands for:","options":["Meaningful","Measurable","Motivational","Management-driven"],"answer":"Measurable"},
            {"question":"Minimum qualification of a head nurse is:","options":["Diploma in nursing","Master degree in nursing","Doctorate in nursing","Bachelor degree in nursing"],"answer":"Bachelor degree in nursing"},
            {"question":"Which of the following is considered a head nurse unit management role?","options":["Directing overall hospital policy","Daily patient care plan creation","Financial audit","Maintenance of supplies & equipment"],"answer":"Maintenance of supplies & equipment"},
            {"question":"What is the COVID-19 problem type in 2019 in Egypt's health sector?","options":["Well-structured problems","Standard problems","Unstructured problems","Routine problems"],"answer":"Unstructured problems"},
            {"question":"Which style is used for solving climate change health effects after 5 years?","options":["Directive style","Behavioral style","Conceptual style","Analytical style"],"answer":"Conceptual style"},
            {"question":"Which type of authority is defined as assure certain responsibility?","options":["Technical authority","Legal authority","Operational authority","Ultimate authority"],"answer":"Operational authority"},
            {"question":"The budget considered as the life blood of an organization is:","options":["Capital budget","Operating budget","Personnel budget","Cash budget"],"answer":"Cash budget"},
            {"question":"Personal satisfaction / cultural / religious values are examples of:","options":["Extrinsic motivation","Intrinsic motivation","Financial motivation","Environmental motivation"],"answer":"Intrinsic motivation"},
            {"question":"Permanent recording of information is defined as:","options":["Reporting","Documentation","Directing","Staffing"],"answer":"Documentation"},
            {"question":"Use a few words to give necessary information refers to:","options":["Accuracy","Conciseness","Thoroughness","Confidentiality"],"answer":"Conciseness"},
            {"question":"Guidance and direction to achieve a certain goal is:","options":["Leadership","Motivation","Supervision","Planning"],"answer":"Supervision"},
            {"question":"Which of the following is considered a Patient Factor affecting staffing?","options":["Educational level of staff","Availability of supplies","Length of stay","Personal policies"],"answer":"Length of stay"},
            {"question":"Which method calculates hours of nursing care needed during a particular shift?","options":["Acuity and complexity of care","Patient length of stay","Environmental auditing","Span of control"],"answer":"Acuity and complexity of care"},
            {"question":"Formal communication authority in an organization is defined as:","options":["Chain of command","Span of control","Unity of command","Departmentation"],"answer":"Chain of command"},
            {"question":"Grouping hospital units into Medical and Surgical units is departmentation by:","options":["Services","Function","Location","Patient"],"answer":"Function"},
            {"question":"Categorizing units into Intensive care and Intermediate care is departmentation by:","options":["Time","Degree","Location","Function"],"answer":"Degree"},
