            {"question":"The causative agent of cholera is:","options":["Salmonella enterica serotype Typhi","Vibrio cholerae","Brucella melitensis","Hepatitis A virus"],"answer":"Vibrio cholerae"},
            {"question":"Vibrio cholerae is described in the lecture as a:","options":["Gram-positive bacterium","Gram-negative bacterium","Virus","Parasite"],"answer":"Gram-negative bacterium"},
            {"question":"Cholera is MOST commonly transmitted through:","options":["Airborne droplets","Fecal-oral transmission through contaminated water or food","Blood transfusion","Direct contact with skin lesions"],"answer":"Fecal-oral transmission through contaminated water or food"},
            {"question":"Which food exposure is specifically associated with cholera transmission in the lecture?","options":["Properly cooked meat only","Raw seafood and vegetables irrigated with contaminated water","Pasteurized dairy products","Canned food only"],"answer":"Raw seafood and vegetables irrigated with contaminated water"},
            {"question":"The incubation period of cholera ranges from:","options":["2 hours to 5 days","5 days to several weeks","7–14 days only","15–50 days"],"answer":"2 hours to 5 days"},
            {"question":"Which clinical manifestation is MOST characteristic of cholera according to the lecture?","options":["Rose-colored spots","Rice-water stools","Flaccid paralysis","Undulating fever"],"answer":"Rice-water stools"},
            {"question":"A patient with cholera develops severe fluid loss, hypotension, and shock. The MOST serious complication if untreated is:","options":["Permanent paralysis","Death due to severe dehydration","Chronic carrier state","Respiratory failure due to paralysis"],"answer":"Death due to severe dehydration"},
            {"question":"Which intervention is included in cholera prevention?","options":["Safe drinking water and sanitation","Avoiding all vaccinations","Blood donor screening","Isolation from animal reservoirs only"],"answer":"Safe drinking water and sanitation"},
            {"question":"Which vaccine route is used for the cholera vaccines mentioned in the lecture?","options":["Intramuscular","Subcutaneous","Oral","Intradermal"],"answer":"Oral"},
            {"question":"According to the lecture, adults and children aged ≥2 years receive the oral cholera vaccine as:","options":["One dose only","Two doses 1–6 weeks apart","Three doses at monthly intervals","Two doses on the same day"],"answer":"Two doses 1–6 weeks apart"},
            {"question":"Protection from the oral cholera vaccine mentioned in the lecture may last up to:","options":["6 months","1 year","2 years","10 years"],"answer":"2 years"},
            {"question":"Which population is MOST specifically identified as a target for cholera vaccination?","options":["All hospitalized patients","Travelers to endemic areas","Patients with hypertension","Only newborn infants"],"answer":"Travelers to endemic areas"},
            {"question":"The causative agent of poliomyelitis is:","options":["Poliovirus, an enterovirus","Hepatitis A virus","Vibrio cholerae","Brucella suis"],"answer":"Poliovirus, an enterovirus"},
