            {"question":"Booster doses for polio vaccination are given at:","options":["6 months and 12 months","18 months and 4 years","Birth and 2 months","4 and 6 months"],"answer":"18 months and 4 years"},
            {"question":"Hepatitis A is caused by:","options":["A Gram-negative bacillus","A non-enveloped RNA virus from the Picornaviridae family","A parasite","A fungal toxin"],"answer":"A non-enveloped RNA virus from the Picornaviridae family"},
            {"question":"Which statement about the reservoir of Hepatitis A is CORRECT?","options":["Domestic animals are the main reservoir","Humans are the reservoir, with no chronic carrier state","Water is the only reservoir","Chronic carriers shed the virus for years"],"answer":"Humans are the reservoir, with no chronic carrier state"},
            {"question":"The incubation period of Hepatitis A is:","options":["2 hours–5 days","7–14 days","15–50 days, with an average of 28 days","Several months only"],"answer":"15–50 days, with an average of 28 days"},
