            {"question":"Which prevention measure may be used after exposure to Hepatitis A?","options":["Vaccine or immunoglobulin","OPV only","Animal vaccination","Antimalarial drugs"],"answer":"Vaccine or immunoglobulin"},
            {"question":"The causative agent of typhoid fever is:","options":["Salmonella enterica serotype Typhi","Vibrio cholerae","Brucella abortus","Poliovirus"],"answer":"Salmonella enterica serotype Typhi"},
